insert into public.programs (id, slug, name, aka, age_group, audience, tagline, description, outcomes, levels, videos, logo, logo_mono, image, accent, notice, sort, published) values
('prog-little-legends', 'little-legends', 'Little Legends', null, '3 – 5.5 years', 'kids', 'A toddler''s journey to sensory exploration', 'Unleash your child''s inner rhythm and watch them twirl, swirl, and shine with joy. Learning and expression come together through our story-based choreography sessions. Through dance, children develop their five senses, enhancing learning abilities and gaining a deeper understanding of movement''s meaning. Give your tiny tots the opportunity to explore the world in a whole new way through dance.', '{}'::text[], '{}'::text[], array['PPVhTnvB-k8','YmrlaaTzaZY','xfKMJ4IPTcI']::text[], '/media/courses/client-logo-5.webp', '/media/client-logo-5.webp', '/media/courses/course-1.webp', '#F2A900', null, 1, true),
('prog-level-up', 'level-up', 'Level Up', 'Flow Course', '5.5 – 7 years', 'kids', 'Lay the groundwork for a lifelong love of dance', 'Lay the groundwork for a lifelong love of dance, focusing on basic rhythm and movement foundations.', array['Basic Rhythm Understanding','Foundations of Dance','Preparing for Next Level','Building Agility']::text[], '{}'::text[], array['gGKb0l_Hl7k','mF9Rf936D_I','uCdrwTvJoOY']::text[], '/media/courses/client-logo-7.webp', null, '/media/courses/course-7.webp', '#2B7DE9', null, 2, true),
('prog-rdep', 'rdep', 'RDEP', 'Raack Dance Educational Program', '7 – 12 years', 'kids', 'Building confidence, creating leaders through dance', 'The RDEP program is all about self-expression and unlocking your dance potential. With Raack''s uniquely curated levels, you''ll groove to the rhythm, master body language, and discover the meaning behind every movement. Our copyrighted music and versatile curriculum will take your dancing to the next level. Boost confidence, enhance concentration, and unleash your inner dance superstar with RAACK.', '{}'::text[], array['Level 1','Level 2']::text[], array['it9Zsj5KcyQ','37nr0wNzar4','BximtcOaEmY']::text[], '/media/courses/client-logo-6.webp', '/media/client-logo-6.webp', '/media/courses/course-2.webp', '#EC1D25', null, 3, true),
('prog-choreo-lab', 'choreo-lab', 'Choreo Lab', null, '7 – 12 years · 13 years & above', 'teens', 'Get inspired, get creative, get groovin''', 'Our Choreolab program is designed to unleash your creativity and keep you on your toes. With Dance of the Month, you''ll explore street styles, learn a new dance piece every month, and become a dancing chameleon. This is the perfect program for passionate dancers seeking instant gratification. Learn trendy moves from the gurus and start making your own.', '{}'::text[], '{}'::text[], array['_rJB38jz6Rc','PgkFtdh9UQc','o87VXsXLpQw']::text[], '/media/courses/client-logo-1.webp', '/media/client-logo-1.webp', '/media/courses/course-3.webp', '#7B3FE4', null, 4, true),
('prog-film-covers', 'film-covers', 'Film Covers', null, '7 – 12 years · 13 years & above', 'teens', 'From screen to stage — groove with filmy tunes', 'Lights, camera, dance! Step into the world of cinema with the Film Covers program, where you''ll groove to the beats of trending film songs. Unleash your inner Bollywood, Kollywood or Dappankuthu star and relive the magic of Indian cinema through high-energy choreography. With dramatic expressions and vibrant moves, you''ll experience the flavourful essence of film music. Join us on the dance floor, have a blast, and become the star of your own cinema!', array['Explore the flavour of dramatic expression in cinema','Opportunity to showcase your talent on stage','Wholesome experience of dancing to film songs','High-energy and entertaining choreography sessions','Experienced and passionate instructors','Fun and vibrant learning environment']::text[], '{}'::text[], array['jFSDM1wMVWg','UKAc2SdY-94','uWW7VA3rgS0']::text[], '/media/courses/client-logo-3.webp', '/media/client-logo-3.webp', '/media/courses/course-4.webp', '#FF5A1F', null, 5, true),
('prog-dance-fitness', 'dance-fitness', 'Dance Fitness', null, 'Adults', 'adults', 'Dance your way to a healthier and happier you!', 'Say goodbye to pain and hello to gains in physical and mental well-being. Our Dance Wellness program offers a unique blend of dance and wellness activities that will uplift your mind, body, and soul. This unique program focuses on the joy of movement and the power of holistic well-being. No forced movements, just pure expression and body awareness. Improve your concentration, keep your mind joyful, look and feel younger by the day.', '{}'::text[], '{}'::text[], '{}'::text[], '/media/courses/client-logo-2.webp', '/media/client-logo-2.webp', '/media/courses/course-5.webp', '#E3358B', null, 6, true),
('prog-just-dance', 'just-dance', 'Just Dance', 'Open Class', '7 – 12 years · 13 years & above', 'all', 'One joy-filled hour a week', 'Our Open Class program is designed to quench your dance thirst and help you last through the week. With vibrant choreography workshops, you''ll learn the art of concentration through movement and boost your confidence on the dance floor. Repair your body and mind while spending just one hour a week with Raack. Join us for joy-filled dance sessions that fit perfectly into your busy schedule!', '{}'::text[], '{}'::text[], array['aQXcVb_yTK8','UhVetG6Dae4','usEkcGvD7A8']::text[], '/media/courses/client-logo-4.webp', '/media/client-logo-4.webp', '/media/courses/course-6.webp', '#1BA8A0', 'Availability varies by studio — please check with your nearest Raack studio.', 7, true)
