insert into public.team_members (id, name, role, vision, body, photo, sort, published) values
('team-ramana-balaji', 'Ramana Balaji', 'Founder', 'I strongly believe that ''Your thoughts create your reality''. Your thought flows freely every instant, similar to your dance moves. There is no limit in innovating, and hence you have a whole path of creativity to own up your dance style.', 'Raack is here to act as a bridge connecting you with the element of dance within you.', '/media/core-team/team-2.webp', 0, true),
('team-kavi-chakravarthy', 'Kavi Chakravarthy', 'Curriculum Head', 'Our vision is to cultivate a curriculum that nurtures a profound understanding of self-expression and fosters creative performance among our students.', 'Each program is designed to unlock the innate potential within every dancer, elevating their skills to meet and exceed international standards while honoring and reinforcing our rich cultural roots. We aim to craft an educational journey that encourages innovation, artistic depth, and technical excellence, empowering our students to shine on the global stage while cherishing our heritage.', '/media/core-team/Kavi-chakravarthi.webp', 1, true),
('team-gugan', 'Gugan', 'Instructor Head', 'Our vision is to equip our instructors with versatile teaching methods, expert technique, and tailored creativity for diverse age groups.', 'We empower them as torch bearers of tradition, technique, creativity, and mentorship. Our goal is to enrich the dance community with skilled, passionate, and globally competitive artists while preserving Raack''s essence as ''The Place for Self-Expression'', blending innovation and excellence in dance education.', '/media/core-team/Gugan.webp', 2, true),
('team-vijay-kumar-b', 'Vijay Kumar B', 'Counsellor Head', 'Our vision is to equip our counsellors with comprehensive knowledge of each course, enabling them to adeptly guide patrons towards courses that best suit their individual needs.', 'We are committed to maintaining a secure and welcoming environment for parents and students alike. Our goal is to foster confident, well-balanced individuals who excel in their artistic pursuits, championing self-discovery and holistic well-being within our dance community.', '/media/core-team/Vijay-Kumar.webp', 3, true),
('team-vibinesh-vijayan', 'Vibinesh Vijayan', 'Event Head', 'Our vision is to curate and execute captivating and culturally enriching events that celebrate the diversity, talent, and artistry within our dance academy.', 'We aim to create immersive experiences that not only entertain but also educate and inspire our audience. By meticulously planning and orchestrating events that showcase the brilliance of our dancers while fostering a sense of community and cultural pride, we strive to establish our academy as a beacon of creativity and excellence in the world of performing arts.', '/media/core-team/Vibinesh.webp', 4, true)
insert into public.events (id, slug, name, subtitle, edition, status, date_text, venue, dates_verified, summary, body, highlights, categories, judging, stat, cover, poster, video, gallery, tickets_url, register, closing, sort, published) values
('event-happy-feet', 'happy-feet', 'Happy Feet', 'In-House Dance Contest', 'Season 3 · 2026', 'upcoming', '30 November', 'To be announced', false, 'An exhilarating in-house dance competition that brings together the vibrant talent from every branch of Raack Academy of Dance — showcasing incredible dance abilities while fostering resilience, sportsmanship, and confidence.', array['We are thrilled to announce "Happy Feet", an exhilarating in-house dance competition that will bring together the vibrant talent from every branch of Raack Academy of Dance.','This spirited event aims not only to showcase the incredible dance abilities of our students but also to foster invaluable qualities such as resilience, sportsmanship, and confidence.']::text[], '[{"title":"Fostering Resilience","body":"Through the ups and downs of preparation, students will learn to persist and overcome obstacles, building a strong foundation of resilience that extends beyond the dance floor."},{"title":"Embracing Sportsmanship","body":"Competitions provide an opportunity to celebrate the achievements of all participants. Win or lose, each dancer will learn the importance of camaraderie, mutual respect, and the joy of celebrating one another''s successes."},{"title":"Cultivating Confidence","body":"Stepping onto a stage, under the spotlight, is a powerful confidence-building experience. \"Happy Feet\" encourages every participant to embrace their uniqueness and perform with courage and self-assurance."}]'::jsonb, array['Little Legends (Ages 3 – 5.5)','RDEP Level 1 (Ages 7 – 12)','RDEP Level 2 (Ages 7 – 12)','Choreo Lab (Ages 7 – 12)','Choreo Lab (Ages 13+)','Film Covers (Ages 7 – 12)','Film Covers (Ages 13+)']::text[], array['Technique and Execution','Artistic Interpretation','Stage Presence and Confidence','Originality and Creativity']::text[], null, '/media/events/happy-feet-2025.webp', '/media/video/happy-feet-poster.webp', '/media/video/happy-feet.mp4', array['/media/gallery/dance-classes-in-chennai.webp','/media/gallery/dance-academy-in-chennai.webp','/media/gallery/dance-classes-for-kids-in-chennai.webp','/media/gallery/dance-classes-for-adults-in-chennai.webp']::text[], null, true, 'Get ready to unleash your dancing prowess and be part of a day filled with rhythm, passion, and pure dance magic. Let''s make "Happy Feet" a celebration of talent, growth, and community! See you on the dance floor!', 0, true),
('event-first-step', 'first-step', 'First Step', 'The Annual Recital', '2027', 'upcoming', 'February 2027', 'To be announced', false, 'Our grand Annual Recital — an event that transcends boundaries and unites our dance community in a celebration of talent, passion, and the pure magic of movement.', array['Get ready for a dance extravaganza like never before! We are thrilled to present the first step of Raack''s journey, our grand Annual Recital — an event that transcends boundaries and unites our dance community in a celebration of talent, passion, and the pure magic of movement.','This is not just a recital; it''s Chennai''s grandest dance gala, a stage where talented participants from all corners of Raack''s extensive network come together to showcase their artistic brilliance. From the youngest Little Legends to the seasoned Adult Achievers, each performer will express their emotions through dance, weaving stories that will leave you mesmerised.']::text[], '[{"title":"Inspiration and Aspiration","body":"Witnessing the dedication and talent of our dancers will inspire you to pursue your own dreams, whether they lie in dance or any other endeavour."},{"title":"Community and Connection","body":"The Annual Recital is a gathering of like-minded individuals who share a passion for dance. It''s a chance to connect and be part of a supportive community."},{"title":"Pure Entertainment","body":"Be prepared to be wowed by the sheer talent and creativity on display. From graceful ballet to energetic hip-hop, there is something for everyone."}]'::jsonb, '{}'::text[], '{}'::text[], '{"value":"4000+","label":"Participants"}'::jsonb, '/media/gallery/Velachery-banner-for-first-step-2026.webp', '/media/video/first-step-poster.webp', '/media/video/first-step.mp4', array['/media/gallery/dance-classes-in-chennai.webp','/media/gallery/dance-academy-in-chennai.webp','/media/gallery/dance-classes-for-kids-in-chennai.webp','/media/gallery/dance-classes-for-adults-in-chennai.webp']::text[], 'https://raackdance.co.in/', true, 'Come, be a part of Raack''s journey as we take the first step towards creating memories that will last a lifetime. Let''s make this year''s Annual Recital an experience that leaves us all spellbound. See you on the dance floor!', 1, true),
('event-camp-raack', 'camp-raack', 'Camp Raack', 'Choreo Camp — Kiddy, Junior & Senior', '2027', 'announced', 'Camp dates coming soon', 'To be announced', false, 'Kiddy Choreo Camp, Junior & Senior Choreo Camp — with a grand dance competition. Competition categories: 7 – 12 years, 13 years & above, and Adults.', array['Kiddy Choreo Camp, Junior & Senior Choreo Camp.','Competition categories: 7 – 12 years | 13 years & above | Adults. Camp dates and the grand dance competition will be announced soon.']::text[], '[]'::jsonb, array['7 – 12 years','13 years & above','Adults']::text[], '{}'::text[], null, '/media/gallery/first.webp', '/media/video/choreo-camp-poster.webp', '/media/video/choreo-camp.mp4', array['/media/gallery/dance-classes-in-chennai.webp','/media/gallery/dance-academy-in-chennai.webp','/media/gallery/dance-classes-for-kids-in-chennai.webp','/media/gallery/dance-classes-for-adults-in-chennai.webp']::text[], 'https://raackdance.co.in/', true, null, 2, true),
('event-heal-the-world', 'heal-the-world', 'Heal The World', 'A Tribute to Michael Jackson', 'Season 4', 'past', '24 & 25 August 2024', 'VR Mall, Chennai', false, 'Raack Academy celebrates unity and world peace through a mega dance flash mob — a tribute to Michael Jackson.', array['Raack Academy orchestrated an awe-inspiring mega dance flash mob featuring students across its branches. This grand event, held at VR Mall Chennai, was dedicated to the iconic Michael Jackson, with the profound purpose of promoting world peace.','The mega dance flash mob, a testament to Raack Academy''s commitment to creativity and unity, drew participants from various branches and backgrounds. The theme, "World Peace", resonated strongly with the participants, showcasing that dance and music can transcend barriers and inspire positive change.','The event was graced by the presence of esteemed celebrities and film music directors, who not only added star power to the occasion but also contributed to the atmosphere of artistic celebration. Their involvement highlighted the bridge between art and social causes that Raack Academy passionately advocates.']::text[], '[]'::jsonb, '{}'::text[], '{}'::text[], '{"value":"1800+","label":"Kids participants"}'::jsonb, '/media/events/events.webp', '/media/video/heal-the-world-poster.webp', '/media/video/heal-the-world.mp4', array['/media/heal-world-images/dance-classes-in-chennai.webp','/media/heal-world-images/dance-academy-in-chennai.webp','/media/heal-world-images/dance-classes-for-kids-in-chennai.webp','/media/heal-world-images/dance-classes-for-adults-in-chennai.webp','/media/heal-world-images/dance-classes-chennai.webp','/media/heal-world-images/dance-academy-chennai.webp','/media/heal-world-images/dance-class-in-chennai.webp','/media/heal-world-images/dance-class-chennai.webp','/media/heal-world-images/best-dance-classes-in-chennai.webp','/media/heal-world-images/best-dance-academy-in-chennai.webp','/media/heal-world-images/best-dance-classes-for-kids-in-chennai.webp','/media/heal-world-images/best-dance-classes-for-adults-in-chennai.webp','/media/heal-world-images/best-dance-classes-chennai.webp','/media/heal-world-images/best-dance-dance-academy-chennai.webp','/media/heal-world-images/best-dance-class-in-chennai.webp','/media/heal-world-images/best-dance-class-chennai.webp']::text[], null, false, null, 3, true)
insert into public.testimonials (id, kind, name, designation, studio, program_slug, quote, photo, consent_status, published, sort) values
('t-student-mudita-mehta', 'student', 'Mudita Mehta', 'Chartered Accountant', null, 'dance-fitness', 'The dance fitness classes at Raack Academy, taken by Preeti, are engaging and fun! The routines are changed from time to time to keep the classes interesting. It''s a great way to burn calories while dancing your heart out, and it''s my stress buster. At work, I can feel a lot of happiness and positive change.', '/media/testimonial/mudita-mehta.webp', 'unknown', true, 0),
('t-student-karthic-sankar-senthippan', 'student', 'Karthic Sankar Senthippan', 'Engineer', null, 'film-covers', 'Sitting at a laptop all day used to make me physically inactive. However, after enrolling in the Film Covers class, I''ve become active throughout the day and can now accomplish much more. The instructor is fantastic, skillfully blending entertainment with the teaching of some impressive moves. I wholeheartedly recommend enrolling in these sessions to enjoy quality time while maintaining your fitness.', '/media/testimonial/karthick.webp', 'unknown', true, 1),
('t-student-meenakshi', 'student', 'Meenakshi', null, null, null, 'The best place to learn dance! The instructor is encouraging and teaches so well that even if you''ve never danced before, you''ll find yourself dancing. The environment is incredibly positive. I always look forward to the weekends for my classes. I''m confident that everyone who comes here will enjoy it and want to continue.', '/media/testimonial/meenakshi.webp', 'unknown', true, 2),
('t-student-athirai', 'student', 'Athirai', 'Dance Enthusiast', null, null, 'Dance has been an integral part of my life. As a classical dancer, I sought out Raack Academy to delve into various styles and explore the intricacies of Western dance. I am now filled with immense happiness and satisfaction, realizing that Raack offers even more for a passionate dancer like myself. The approach to dance at Raack is profoundly unique and blissful, expanding my thought process in ways I never imagined.', '/media/testimonial/athirai.webp', 'unknown', true, 3),
('t-student-sivaranjini', 'student', 'Sivaranjini', 'Toddler Parent', null, 'little-legends', 'I''ve enrolled my 3-year-old son in the Little Legends program, and he absolutely adores coming to Raack for the customized monthly themes, soundtracks, and props. The instructor is friendly and caters to students of all ages and skill levels. It''s truly the best dance studio! I wholeheartedly recommend it to anyone eager to learn dance.', '/media/testimonial/sivaranjani.webp', 'unknown', true, 4),
('t-student-dr-p-elanthirayan', 'student', 'Dr. P. Elanthirayan', 'Paediatric Surgeon', null, null, 'My journey with Raack has been delightful. Starting with my son''s classes in Raack Cuddalore, I soon joined in. It''s been a fun and enriching experience. Here, both children and adults learn to be themselves without inhibitions. The instructors are highly professional and connect well with everyone. Mrs. Purni, the proprietor, is always enthusiastic, showcasing our kids'' talents and keeping us motivated. At Raack, we''re one big family of fun and frolic!', '/media/testimonial/elanthirayan.webp', 'unknown', true, 5),
('t-franchise-muthu-kumar', 'franchise', 'Muthu Kumar', 'Franchise Partner', 'Pallikaranai', null, 'In 2020, we envisioned creating a nurturing art and dance community for kids'' mental well-being. Pallikaranai was our chosen location, with a professional team by our side. When it came to dance, ''RAACK'' was the clear choice, and it remains my best decision to date. It''s a space for self-expression where our ideas are valued. With strong leaders and mentors, we work as a close-knit family. So far, it''s been an amazing journey towards becoming the top dance brand, not just in Pallikaranai, but across the country. This is only the beginning.', '/media/franchise-head/muthu.webp', 'unknown', true, 0),
('t-franchise-smitha-arun', 'franchise', 'Smitha Arun', 'Franchise Partner', 'Kolathur', null, 'I became a Raack franchisee at the Kolathur centre, driven by my love for children and dance. It''s been a fulfilling journey. Seeing the kids'' smiles and their dedication to mastering dance steps reaffirms my decision. The genuine joy in parents'' eyes is heartwarming. Raack has provided invaluable support, especially since I''m not a dancer. Excited for more years of learning and spreading happiness with parents and children!', '/media/franchise-head/smitha.webp', 'unknown', true, 1),
('t-franchise-aishwarya', 'franchise', 'Aishwarya', 'Franchise Partner', 'Old Perungalathur', null, 'Starting in RAACK during lockdown was a unique challenge, but it''s time to redefine the norm! Grateful that dance lets us spread positivity, uplift our staff, and give back to the community. Creative courses ignite our students'' imagination, celebrating its beauty while fostering competition and participation. The Founder''s vision, the Core Team, and the CEO''s genuine care for every Franchise Partner set it apart. Proud to be part of the RAACK FAMILY!', '/media/franchise-head/aiswarya.webp', 'unknown', true, 2),
('t-franchise-purni-magesh', 'franchise', 'Purni Magesh', 'Franchise Partner', 'Cuddalore', null, 'As a female entrepreneur, I''m proud to be part of Raack, South India''s premier dance academy. My mission: thrive with passion, live with compassion, and embrace life''s vibrancy, fun, and style. Taking this franchise aligns perfectly with that goal. Dance is my everything and nothing all at once, providing balance in life. Raack is the perfect place for my mission.', '/media/franchise-head/purni-magesh.webp', 'unknown', true, 3),
('t-staff-abirami', 'staff', 'Abirami', 'Raack Team', null, null, 'As a female instructor at Raack Academy of Dance, I have found an incredibly safe and nurturing environment that prioritizes both physical and mental well-being. This empowering space has allowed me to deepen my expertise, fostering an enriching atmosphere where knowledge is cultivated and satisfaction is paramount.', '/media/careers/abirami.webp', 'unknown', true, 0),
('t-staff-rajvarma', 'staff', 'Rajvarma', 'Raack Team', null, null, 'The leadership team at Raack Dance Academy truly cares about the well-being and success of their employees.', '/media/careers/rajvarma.webp', 'unknown', true, 1),
('t-staff-joshi', 'staff', 'Joshi', 'Raack Team', null, null, 'What drew me to Raack Academy of Dance is the opportunity to make a real difference in the lives of our students.', '/media/careers/joshi.webp', 'unknown', true, 2)
