insert into public.careers (id, title, type, summary, requirements, apply, published, sort) values
('career-instructor', 'Instructor', 'Full-time', 'Join Raack Dance Academy as a skilled Instructor! Teach, provide feedback, and inspire a love for dance. You play a key role in helping students develop their skills and passion for dance. Send us your dance videos, attend our auditions, get selected — and the rest would be history.', array['Passion for Dance: Enthusiasm for dance and a genuine desire to share your knowledge and skills with others.','Dance Proficiency: Proficient in the specific dance style(s) you will be teaching (e.g. hip-hop, house, contemporary). Demonstrated skill in choreography and dance technique.','Teaching Experience: Prior experience as a dance instructor is preferred but not mandatory for entry-level positions.','Communication Skills: Clear and effective verbal communication to instruct and demonstrate dance moves. Ability to provide constructive feedback to students.','Patience and Adaptability: Ability to work with students of varying ages, skill levels, and learning styles. Flexibility to adapt teaching methods to individual needs.','Safety Awareness: Knowledge of proper warm-up and stretching techniques to prevent injuries. Ability to create a safe and supportive learning environment.','Leadership and Organization: Strong leadership skills to guide and motivate students during classes and rehearsals. Organizational skills to plan and manage class schedules and performances.','Professionalism: Punctuality, reliability, and a professional demeanor when interacting with students, parents, and colleagues.','Continuous Learning: Willingness to stay updated on current trends, techniques, and best practices in dance instruction.']::text[], 'Apply now with your resume, dance videos/showreel, and a brief cover letter sharing your interest in joining Raack Dance Academy.', true, 0),
('career-counsellor', 'Counsellor', 'Full-time', 'Join Raack Dance Academy as a skilled Counsellor! Send us your resume, attend our interview, get selected — and the rest would be history.', array['Education and Certification: Bachelor''s degree in any field or a related field.','Experience: Minimum of 2 years of experience in counselling or a related field. Demonstrated experience working with diverse populations and age groups.','Counselling Skills: Strong interpersonal and communication skills; empathy, active listening, and the ability to establish rapport with clients.','Empathy and Compassion: Demonstrated ability to provide emotional support and create a safe, non-judgmental environment for clients.','Adaptability: Ability to explain the custom dance course to meet the unique needs and goals of each client.','Documentation and Record-Keeping: Proficient in maintaining accurate and detailed client records.','Continuous Learning: Commitment to staying updated on the latest professional development opportunities.','Teamwork: Ability to collaborate with and support the team.']::text[], null, true, 1),
('career-branch-manager', 'Branch Manager', 'Full-time', 'A Branch Manager at a dance studio oversees day-to-day operations, manages staff, schedules classes, and ensures customer satisfaction. You are responsible for the smooth functioning of the branch, from financial management to maintaining a safe and welcoming environment for students.', array['Operations Management: Oversee day-to-day operations of the dance studio branch. Ensure smooth functioning of classes, rehearsals, and events.','Staff Supervision: Recruit, train, and manage dance instructors and support staff.','Scheduling and Coordination: Develop and maintain class schedules, ensuring optimal utilization of studio space and resources.','Customer Relations: Interact with parents, students, and clients to address inquiries, concerns, and feedback.','Financial Management: Monitor and manage the branch budget, including revenue, expenses, and profitability.','Marketing and Promotion: Work with the marketing team to attract new students and retain existing ones. Organize and promote events, workshops, and performances.','Facility Maintenance and Safety: Ensure the cleanliness, safety, and maintenance of the studio space. Implement safety protocols and emergency procedures.','Curriculum Development: Collaborate with dance instructors to develop and refine class curriculum aligned with the studio''s teaching philosophy.','Administrative Tasks: Handle scheduling, payroll, and record-keeping. Maintain accurate student and staff records.','Reporting and Communication: Provide regular reports to management on branch performance, including financial metrics, enrollment numbers, and customer feedback.']::text[], 'Apply now with your resume and a brief cover letter sharing your interest in joining Raack Dance Academy.', true, 2),
('career-designer', 'Designer', 'Full-time', 'Join Raack Dance Academy as a skilled designer! Create captivating and visually stunning graphic design that showcases the artistry of dance. Collaborate with our creative team to produce engaging content, ensuring seamless integration of graphics. Stay updated with industry trends and bring your creative flair to enhance our storytelling.', array['Proven experience in designing.','Proficiency in industry-standard design software.','Strong understanding of design techniques.','Excellent time management and collaboration skills.','Passion for dance and artistic storytelling.']::text[], 'Apply now with your resume, portfolio, and a brief cover letter sharing your interest in joining Raack Dance Academy.', true, 3),
('career-video-editor', 'Video Editor', 'Full-time', 'Join Raack Dance Academy as a skilled Video Editor! Create captivating and visually stunning videos that showcase the artistry of dance. Collaborate with our creative team to produce engaging content, ensuring seamless integration of footage, music, and graphics. Stay updated with industry trends and bring your creative flair to enhance our video storytelling.', array['Proven experience in video editing.','Proficiency in industry-standard editing software.','Strong understanding of video production techniques.','Excellent time management and collaboration skills.','Passion for dance and artistic storytelling.']::text[], 'Apply now with your resume, portfolio/showreel, and a brief cover letter sharing your interest in joining Raack Dance Academy.', true, 4)
