insert into public.pages (slug, title, meta_description, heading, intro, published) values
('home', 'Raack Academy of Dance — Dance Classes for Kids & Adults in Chennai and South India', 'Raack Academy of Dance: 45+ studios across Chennai and South India. Programs for toddlers, kids, teens and adults — Little Legends, RDEP, Choreo Lab, Film Covers, Dance Fitness. Book a free trial.', null, null, true),
('about', 'About Raack — The Amplifiers of Dance as a Way of Life', 'Raack is an independent dance academy for kids and adults. Meet our founder Ramana Balaji and core team, and discover our philosophy of movement-based art.', null, null, true),
('programs', 'Dance Programs for Toddlers, Kids, Teens & Adults | Raack', 'Explore Raack dance programs: Little Legends (3–5.5 yrs), Level Up (5.5–7), RDEP (7–12), Choreo Lab, Film Covers and Dance Fitness for adults.', null, null, true),
('studios', 'Find a Raack Dance Studio Near You | 45+ Studios', 'Find your nearest Raack Academy of Dance studio in Chennai, Puducherry, Cuddalore, Chidambaram, Thanjavur, Kumbakonam, Trichy and Bengaluru. Addresses, phone numbers and class schedules.', null, null, true),
('online-academy', 'Online Dance Classes for the Global Tamil Community | Raack Online Academy', 'Raack Online Academy: connecting Tamils globally through the art of dance. Live and recorded classes, structured curriculum, one-on-one and batch options. Free online trial.', null, null, true),
('events', 'Events & Experiences — Happy Feet, First Step, Camp Raack | Raack', 'Raack''s signature events: Happy Feet in-house contest, First Step annual recital, Camp Raack choreo camp and the Heal The World flash mob.', null, null, true),
('faculty-academy', 'Faculties Training Academy — Become a Dance Coach | Raack', 'Raack''s Faculties Training Academy trains dance coaches and mentors in technique, teaching methodology, choreography and communication.', null, null, true),
('gallery', 'Gallery — Performances, Events & Studios | Raack Academy of Dance', 'Photos and videos from Raack performances, events, programs and studios.', null, null, true),
('careers', 'Careers at Raack — Instructor, Counsellor, Branch Manager & More', 'Join the Raack Dance Academy team. Open roles: Instructor, Counsellor, Branch Manager, Designer and Video Editor.', null, null, true),
('franchise', 'Open a Raack Dance Studio — Franchise Opportunities', 'Start your own Raack dance studio at low investment, backed by an established brand, training, operations support and an exclusive territory.', null, null, true),
('contact', 'Contact Raack Academy of Dance', 'Call +91 90030 24113 or send an enquiry. Find your nearest Raack studio across Chennai and South India.', null, null, true),
('book-a-free-trial', 'Book a Free Trial Dance Class | Raack', 'Book a free trial class at your nearest Raack studio or online.', null, null, true)
